import 'package:flutter/material.dart';

class AddHabitScreen extends StatefulWidget {
  const AddHabitScreen({super.key});

  @override
  State<AddHabitScreen> createState() => _AddHabitScreenState();
}

class _AddHabitScreenState extends State<AddHabitScreen> {
  final _controller = TextEditingController();

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _submit() {
    final name = _controller.text.trim();
    if (name.isEmpty) return;
    Navigator.pop(context, name);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Add Habit')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            TextField(controller: _controller),
            const SizedBox(height: 12),
            ElevatedButton(onPressed: _submit, child: const Text('Save')),
          ],
        ),
      ),
    );
  }
}

class Habit {
  const Habit({
    required this.id,
    required this.name,
    required this.streak,
  });

  final String id;
  final String name;
  final int streak;

  factory Habit.fromJson(Map<String, dynamic> json) {
    return Habit(
      id: json['id'] as String,
      name: json['name'] as String,
      streak: json['streak'] as int,
    );
  }

  Map<String, dynamic> toJson() => {
        'id': id,
        'name': name,
        'streak': streak,
      };
}

import 'dart:convert';
import 'package:http/http.dart' as http;

class HabitService {
  Future<List<Habit>> fetchHabits() async {
    final response = await http.get(Uri.parse('https://example.com/api/habits'));

    if (response.statusCode != 200) {
      throw Exception('Failed to load habits');
    }

    final data = jsonDecode(response.body) as List<dynamic>;
    return data
        .map((item) => Habit.fromJson(item as Map<String, dynamic>))
        .toList();
  }
}

class HabitListScreen extends StatelessWidget {
  HabitListScreen({super.key});

  final HabitService service = HabitService();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Habits')),
      body: FutureBuilder<List<Habit>>(
        future: service.fetchHabits(),
        builder: (context, snapshot) {
          if (snapshot.connectionState != ConnectionState.done) {
            return const Center(child: CircularProgressIndicator());
          }
          if (snapshot.hasError) {
            return Center(child: Text(snapshot.error.toString()));
          }

          final habits = snapshot.data ?? const [];
          return ListView.builder(
            itemCount: habits.length,
            itemBuilder: (context, index) {
              final habit = habits[index];
              return HabitTile(
                name: habit.name,
                streak: habit.streak,
                onTap: () {},
              );
            },
          );
        },
      ),
    );
  }
}

